"""Classify final test failures using refusals and previously replayed base witnesses."""
import json,sys,xml.etree.ElementTree as ET
from pathlib import Path
ROOT=Path(__file__).resolve().parent
mode=sys.argv[1];folder=ROOT/'evidence/round2/tests'
base=json.loads((ROOT/'evidence/tests/final_full_failure_classification.json').read_text())
known={r['node'] for r in base['full_failures']}
receipts=[json.loads(line) for line in (folder/'seed_refusals.jsonl').read_text().splitlines()]
def normalized(node):
    file,rest=node.split('::',1)
    return file.removesuffix('.py').replace('/','.')+'::'+rest
refused={normalized(r['node_id']) for r in receipts if '::' in r.get('node_id','')}
# Verified indirect witnesses: the map runner catches refusal and leaves no row;
# the isolated pygame child wraps refusal in CalledProcessError. Require their
# exact failure shape AND a matching receipt; do not blanket-classify by node.
indirect={
 'tests.benchmark.test_hybrid_rule_v4_doorway_regression::test_v4_avoids_the_v3_doorway_pedestrian_collision[classic_doorway_high-111]':('IndexError: list index out of range',111,'environment_factory.py'),
 'tests.benchmark.test_hybrid_rule_v4_doorway_regression::test_v4_avoids_the_v3_doorway_pedestrian_collision[classic_doorway_low-120]':('IndexError: list index out of range',120,'environment_factory.py'),
 'tests.test_lazy_pygame_init::test_debug_robot_env_materializes_pygame_on_first_render':('subprocess.CalledProcessError:',123,'env_util.py'),
}
def indirect_refusal(node,message):
 if node not in indirect:return False
 prefix,seed,location=indirect[node]
 return message.startswith(prefix) and any(normalized(r['node_id'])==node and r['seed']==seed and location in ''.join(r['stack']) for r in receipts if '::' in r.get('node_id',''))
tree=ET.parse(folder/(mode+'_junit.xml'))
rows=[]
for case in tree.findall('.//testcase'):
    bad=case.find('failure')
    if bad is None:bad=case.find('error')
    if bad is None:continue
    node=case.attrib['classname']+'::'+case.attrib['name']
    message=bad.attrib.get('message','')
    if 'LaneSeedRefusal' in (bad.text or '') or 'LaneSeedRefusal' in message:
        disposition='guard refusal before reset; recorded and continued'
    elif indirect_refusal(node,message):
        disposition='guard refusal before reset; verified wrapped/empty-row witness, recorded and continued'
    elif node in known:
        disposition='inherited; same node failed on exact CALFIT base in retained replay'
    else:disposition='requires investigation'
    rows.append(dict(node=node,kind=bad.tag,message=message,disposition=disposition))
result={'mode':mode,'summary':tree.getroot()[0].attrib,'failures':rows,
        'refusals':sum('guard refusal' in r['disposition'] for r in rows),
        'inherited':sum('inherited' in r['disposition'] for r in rows),
        'unknown':sum('investigation' in r['disposition'] for r in rows)}
(folder/(mode+'_failure_classification.json')).write_text(json.dumps(result,indent=2))
print({k:v for k,v in result.items() if k!='failures'})
for r in rows:
    if 'investigation' in r['disposition']:print(r['node'],r['message'][:250])

