"""Lane-only seed interception with exact node and stack receipts."""
import json, os, random, traceback
from pathlib import Path
import numpy as np

ROOT=Path(__file__).parent
SEALED={50036,50140,50331,50403,50813,51339,51709,51767,52094,52175,52257,52671,52850,52971,53020,53198,53239,53636,53671,53779,55022,55379,55568,56170,56966,57077,57113,57494,57943,59019}
CURRENT_NODE=None
EXISTING=json.loads((ROOT/"evidence/tests/origin_main_existing_nodes.json").read_text())["functions"]
class LaneSeedRefusal(RuntimeError):pass

def checked(value):
 if isinstance(value,(int,np.integer)) and (111<=int(value)<=140 or int(value) in SEALED):
  node=CURRENT_NODE or os.environ.get('PYTEST_CURRENT_TEST','').rsplit(' ',1)[0]
  parts=(node or '').split('::')
  existing=len(parts)>1 and parts[-1].split('[')[0] in EXISTING.get(parts[0],[])
  permitted=False
  receipt={'existing_main_lineage':existing,'seed':int(value),'node_id':node,'pid':os.getpid(),'status':'existing test permitted under ruling' if permitted else 'refused before RNG/reset/step','stack':traceback.format_stack()[:-1]}
  with (ROOT/'evidence/round2/tests/seed_refusals.jsonl').open('a') as out:out.write(json.dumps(receipt)+'\n')
  if permitted:return value
  raise LaneSeedRefusal(f'protected RNG request {value} refused; node={CURRENT_NODE}')
 return value

def pytest_configure(config):
 for owner,name in [(np.random,'seed'),(np.random,'default_rng'),(random,'seed')]:
  original=getattr(owner,name)
  def guarded(value=None,*args,_original=original,**kwargs):return _original(checked(value),*args,**kwargs)
  setattr(owner,name,guarded)

def pytest_runtest_setup(item):
 global CURRENT_NODE
 CURRENT_NODE=item.nodeid

# Latest ruling: guard BEFORE reset body, also guard an explicit applied seed before step.
def pytest_sessionstart(session):
 import importlib,functools
 for module,name in [('robot_env','RobotEnv'),('pedestrian_env','PedestrianEnv'),('multi_robot_env','MultiRobotEnv'),('crowd_sim_env','CrowdSimEnv'),('shared_world','SharedWorldRunner')]:
  cls=getattr(importlib.import_module('robot_sf.gym_env.'+module),name)
  for method in ['reset','step']:
   original=getattr(cls,method,None)
   if original is None:continue
   @functools.wraps(original)
   def fenced(self,*args,_original=original,_method=method,**kwargs):
    if _method=='reset':
     requested=kwargs.get('seed',args[0] if args else None)
     checked(requested)
    else:
     checked(getattr(self,'applied_seed',None))
    return _original(self,*args,**kwargs)
   setattr(cls,method,fenced)

