     rows[(mode,suite,arm,seed,scene)]=er;runtime_rows.append(er)
    for f in [d/'identity.json',d/'completed.json',d/'spawn_receipts.json',path]:members[str(f.relative_to(a.root.parent))]=hashlib.sha256(f.read_bytes()).hexdigest()
    for r in data:
     key=(mode,suite,arm,seed,r['scenario_id'])
     if key in rows or r['seed']!=seed or r['git_hash']!=identity['head_sha']:raise ValueError('episode identity mismatch')
     r['spawn_receipt']=resets[r['scenario_id']]
     if r.get('spawn_validity') is None:raise ValueError('completed row lost project spawn validity')
     physics=r.get('algorithm_metadata',{}).get('pedestrian_physics')
     if mode=='on':
      if not physics or physics['pedestrian_contact']['radius_m']!=.28 or physics['pedestrian_contact']['law']!='projection_v1' or physics['wall']['law']!='bounded_edge_v1':raise ValueError('inactive opt-in law')
      wall=r['algorithm_metadata']['obstacle_force_law']['sites']['fast_pysf']
      if wall['law_version']!='bounded_edge_v1':raise ValueError('runtime wall record disagreement')
     elif physics is not None:raise ValueError('default law record changed')
     rows[key]=r
if len(heads)!=1 or len(drivers)!=1:raise ValueError('mixed robot producer heads/drivers')
def slim(r):
 m=r.get('metrics',{})
 return {k:r.get(k) for k in ['status','termination_reason','steps']}|{'metrics':{k:m.get(k) for k in ['success','collisions','ped_collision_count','obstacle_collision_count','min_clearance','deadlock','failure_to_progress']}}
def trace_info(off,on):
