 info={'paired_trace_steps':min(len(ot),len(nt)),'first_pedestrian_position_change_step':None,'first_robot_position_change_step':None,'last_2s_min_clearance_m':None,'last_2s_robot_displacement_m':None,'nearest_pedestrian_at_termination':None}
 for x,y in zip(ot,nt):
