 return info
regressions=[];improvements=[];paired=[]
for key,on in rows.items():
 if key[0]!='on':continue
 off=rows[('off',*key[1:])];os=slim(off);ns=slim(on)
 pair={'suite':key[1],'planner':key[2],'seed':key[3],'scenario':key[4],'off':os,'on':ns}
 paired.append(pair)
 bucket=summaries.setdefault(key[1]+'/'+key[2],{'pairs':0,'off_status':collections.Counter(),'on_status':collections.Counter(),'new_goal_failures':0,'new_collision_failures':0,'empty_metric_changes':0,'empty_law_metadata_changes':0,'new_runtime_failures':0,'off_collisions':0,'on_collisions':0,'avoided_collision_rows':0,'new_successes':0})
 bucket['off_collisions']+=int(off.get('metrics',{}).get('collisions',0));bucket['on_collisions']+=int(on.get('metrics',{}).get('collisions',0))
