 elif info['first_pedestrian_position_change_step'] is not None and newgoal and decision.get('selected_source')=='static_protective_stop' and decision.get('moving_rejection_counts',{}).get('static_collision',0)>0 and info['last_2s_robot_displacement_m']==0:
